import numpy as np
def comps(I):
    bg=Counter(x for row in I for x in row).most_common(1)[0][0]
    H,W=len(I),len(I[0]); seen=[[False]*W for _ in range(H)]; cl=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and not seen[r][c]:
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and I[ny][nx]!=bg and not seen[ny][nx]: stack.append((ny,nx))
                cl.append(comp)
    return bg,cl
