                    if seen[y][x]: continue
                    seen[y][x]=True; comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and I[ny][nx]!=bg and not seen[ny][nx]: stack.append((ny,nx))
                comps.append(comp)
    for comp in comps:
