import os,re
from collections import defaultdict, Counter

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

def comps(I,bg):
    H,W=len(I),len(I[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; comp=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in comp or I[a][b]==bg: continue
                    comp.add((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and I[x][y]!=bg and (x,y) not in comp:
                                st.append((x,y))
                seen|=comp; out.append(sorted(comp))
    return out

def analyze():
    res=[]
    for nm in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
        I=G[nm+' input']; O=G[nm+' output']
        H,W=len(I),len(I[0])
        cnt=Counter(x for row in I for x in row); bg=cnt.most_common(1)[0][0]
        fg=[v for v in cnt if v!=bg][0]
        cs=comps(I,bg)
        for comp in cs:
            cells=set(comp); rows=sorted(cells)
            solid = len(rows)==1
            for r in rows:
                colset=sorted(c for rr,c in cells if rr==r)
                end=max(colset)
                ch = 'X' if O[r][end+1]==1 else ('.' if O[r][end]==fg else '?')
                # check which cols between end+1..W-1 became 1 in this row
                new=[c for c in range(end+1,W) if O[r][c]==1 and I[r][c]!=1]
                oc_c=[sum(1 for o in cs if o is not comp and any((rr,c) in o for rr in range(H))) for c in range(W)]
                res.append(dict(name=nm,row=r,col=end,label=ch,new=new,
                                start=min(colset),rows_in_comp=rows,solid=solid,
                                other_cols=[c for c,cc in enumerate(oc_c) if cc and c>end]))
    return res
A=analyze()
for a in sorted(A,key=lambda x:(x['name'],x['row'])): print(a)

