def fill(I, gap_min=3):
    Hh=len(I); Ww=len(I[0])
    cnt=Counter(v for row_ in I for v in row_)
    bg=cnt.most_common(1)[0][0]
    Out=[row[:] for row in I]; seen=set()
    for ri in range(Hh):
        for ci in range(Ww):
            if I[ri][ci]!=bg and (ri,ci) not in seen:
                st=[(ri,ci)]; comp=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in comp or I[a][b]==bg: continue
                    comp.add((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
                            x=a+da;y=b+db
                            if 0<=x<Hh and 0<=y<Ww and I[x][y]!=bg and (x,y) not in comp:
                                st.append((x,y))
                seen|=comp
                rws=sorted({r for r,_ in comp})
                brr=None; besti=-1
                for rr_ in rws:
                    cs_=sorted([c for _,c in comp if _==rr_])
                    if mrlen(cs_)>besti:
                        besti=mrlen(cs_); brr=rr_
                bend=max(c for _,c in comp if _==brr)
                gap=Ww-bend-1
                if gap>=gap_min:
                    for c in range(bend+1,Ww):
                        if Out[brr][c]==bg: Out[brr][c]=1
                for rr_ in rws:
                    if rr_==brr: continue
                    e=max(c for _,c in comp if _==rr_)
                    for kk in range(2,Ww-e,2):
                        nxt=e+kk
                        if nxt>=Ww or Out[rr_][nxt]!=bg: break
                        Out[rr_][nxt]=1
    return Out

