def f(I):
    Hh=len(I); Ww=len(I[0])
    cnt=Counter(v for r_ in I for v in r_); bg=cnt.most_common(1)[0][0]
    O=[r[:] for r in I]
    # connected components of fg
    seen=[[False]*Ww for _ in range(Hh)]
    comps=[]
    for r in range(Hh):
        for c in range(Ww):
            if I[r][c]!=bg and not seen[r][c]:
                st=[(r,c)]; comp=[]
                while st:
                    rr,cc=st.pop()
                    if seen[rr][cc]: continue
                    seen[rr][cc]=True; comp.append((rr,cc))
                    for da,db in((-1,0),(1,0),(0,-1),(0,1)):
                        x,y=rr+da,cc+db
                        if 0<=x<Hh and 0<=y<Ww and I[x][y]!=bg and not seen[x][y]: st.append((x,y))
                comps.append(comp)
    best=None  # (maxlen, comp)
    for comp in comps:
        runs={}
        for rr,cc in comp: runs.setdefault(rr,[]).append(cc)
        maxlen=max(max(runs[r])-min(runs[r])+1 for r in runs)
        if best is None or maxlen>best[0]: best=(maxlen,comp)
    anchor=best[1]; emax=max(c for _,c in anchor)
    # anchor: er = max col of anchor
    anc_max=max(c for rr,c in anchor)
    for rr,cc in anchor:
        for c in range(anc_max,Ww): O[rr][c]=1
    for comp in comps:
        if comp is anchor: continue
        rer=max(c for rr,c in comp)
        for rr,cc in comp:
            for c in range(rer+2,Ww-1,2):
                if O[rr][c]==bg: O[rr][c]=1
    return O

