import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_ID'])
    t=open(d+'.txt').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
